-- Block 1: exercises
INSERT INTO exercises (name, muscle_group, difficulty, equipment, tracking_type, description, instructions, muscles_primary, muscles_secondary, tips, common_mistakes) VALUES
(
  'Rozpiętki na bramie z wyciągu górnego',
  'chest',
  'intermediate',
  'cable',
  'reps',
  'Rozpiętki na bramie z wyciągu górnego to ćwiczenie izolowane, które koncentruje się na rozwijaniu mięśni klatki piersiowej. Wykonywane z użyciem wyciągu górnego, angażuje również mięśnie ramion i stabilizatory.',
  ARRAY['Ustaw wyciągi na wysokości ramion.', 'Stań w środku bramy, chwyć uchwyty i zrób krok do przodu jedną nogą, aby ustabilizować pozycję.', 'Z lekkim zgięciem w łokciach, rozłóż ręce na boki, aż poczujesz rozciąganie w klatce piersiowej.', 'Powoli przyciągnij ręce do siebie przed klatką piersiową, utrzymując napięcie w mięśniach.', 'Powtórz ruch przez określoną liczbę powtórzeń.'],
  ARRAY['Klatka piersiowa'],
  NULL,
  ARRAY['Utrzymuj lekko zgięte łokcie przez cały ruch, aby zmniejszyć obciążenie stawów.', 'Skup się na kontrolowanym ruchu i unikaj szarpania.', 'Oddychaj regularnie - wydech przy zbliżaniu rąk, wdech przy ich rozkładaniu.', 'Utrzymuj stabilną pozycję ciała, nie kołysz się do przodu ani do tyłu.'],
  ARRAY['Zaczynanie z kablami ustawionymi zbyt wysoko lub zbyt nisko, co prowadzi do niewłaściwego ukierunkowania mięśni klatki piersiowej.', 'Pozwalanie na nadmierne zginanie łokci, co przenosi skupienie z klatki piersiowej na ramiona.', 'Używanie rozpędu do huśtania kablami zamiast kontrolowanych ruchów, co zmniejsza zaangażowanie mięśni.', 'Nieutrzymywanie lekkiego zgięcia w łokciach, co zwiększa obciążenie stawów barkowych.', 'Nadmierne prostowanie ramion na końcu ruchu, co grozi kontuzją barku.', 'Nieściąganie łopatek, co może prowadzić do złej postawy i nieskutecznej aktywacji klatki piersiowej.', 'Ustawianie zbyt dużego ciężaru, co powoduje załamanie formy i zmniejszenie zakresu ruchu.', 'Pochylanie się zbyt daleko do przodu lub do tyłu, co kompromituje równowagę i ukierunkowuje niewłaściwe grupy mięśniowe.', 'Nieprawidłowe ustawienie nadgarstków względem przedramion, co prowadzi do nadwyrężenia nadgarstków.', 'Zaniedbywanie zaangażowania mięśni brzucha, co może skutkować niestabilnością i złą formą.']
),
(
  'Pompki na odwróconych dłoniach',
  'chest',
  'beginner',
  'bodyweight',
  'reps',
  'Pompki na odwróconych dłoniach to zaawansowane ćwiczenie angażujące głównie mięśnie klatki piersiowej, tricepsy oraz przednie aktony mięśni naramiennych. Wymaga dużej siły nadgarstków i stabilności, dlatego nie jest zalecane dla początkujących. Ćwiczenie to wzmacnia górną część ciała i poprawia ogólną wytrzymałość mięśniową.',
  ARRAY['Rozpocznij w pozycji do pompki, z rękami rozstawionymi na szerokość barków.', 'Odwróć dłonie tak, aby palce były skierowane w stronę nóg.', 'Utrzymuj ciało w linii prostej od głowy do pięt, napinając mięśnie brzucha i pośladków.', 'Zginaj łokcie, obniżając ciało w kierunku podłogi, aż klatka piersiowa prawie dotknie podłoża.', 'Zatrzymaj się na chwilę, a następnie wyprostuj ramiona, wracając do pozycji wyjściowej.'],
  ARRAY['Klatka piersiowa'],
  ARRAY['Brzuch', 'Przedramiona', 'Barki', 'Triceps'],
  ARRAY['Upewnij się, że nadgarstki są dobrze rozgrzane przed rozpoczęciem ćwiczenia.', 'Jeśli czujesz ból w nadgarstkach, przerwij ćwiczenie i skonsultuj się z trenerem.', 'Kontroluj ruchy, unikając gwałtownych opadów ciała.', 'Oddychaj regularnie – wdech podczas opuszczania ciała, wydech przy powrocie do pozycji wyjściowej.', 'Skup się na utrzymaniu stabilnej pozycji ciała przez cały czas trwania ćwiczenia.'],
  ARRAY['Umieszczanie rąk zbyt daleko od siebie, co zmniejsza stabilność i kontrolę.', 'Pozwalanie łokciom na nadmierne rozchodzenie się, co zmniejsza zaangażowanie nadgarstków.', 'Opuszczanie bioder, co prowadzi do złego ustawienia i zmniejszonej aktywacji mięśni brzucha.', 'Nieutrzymywanie nadgarstków w neutralnej pozycji, co zwiększa obciążenie stawów.', 'Wykonywanie ruchu zbyt szybko, co kompromituje kontrolę i skuteczność.', 'Nieutrzymywanie prostej linii od głowy do pięt, co powoduje niewłaściwe ustawienie.', 'Zaniedbywanie angażowania mięśni brzucha, co skutkuje opadającą środkową częścią ciała.', 'Nadmierne zginanie nadgarstków, co grozi napięciem lub dyskomfortem.', 'Używanie ograniczonego zakresu ruchu, co zmniejsza aktywację mięśni.', 'Pozwalanie na zapadanie się ramion, co zmniejsza zaangażowanie górnej części ciała.']
),
(
  'Wyciskanie sztangi na podłodze',
  'chest',
  'intermediate',
  'barbell',
  'reps',
  'Wyciskanie sztangi na podłodze to ćwiczenie siłowe koncentrujące się na rozwijaniu mięśni klatki piersiowej, tricepsów oraz przednich części mięśni naramiennych. Ćwiczenie to jest wykonywane w pozycji leżącej na podłodze, co ogranicza zakres ruchu i zmniejsza obciążenie stawów barkowych, czyniąc je bezpieczniejszym dla osób z problemami w tych obszarach.',
  ARRAY['Połóż się płasko na podłodze, z nogami ugiętymi w kolanach i stopami płasko na ziemi.', 'Chwyć sztangę nachwytem, dłonie rozstawione nieco szerzej niż szerokość barków.', 'Unieś sztangę z podłogi i ustaw ją nad klatką piersiową, ramiona wyprostowane.', 'Powoli opuszczaj sztangę w kierunku klatki piersiowej, aż łokcie dotkną podłogi.', 'Zatrzymaj ruch na chwilę, a następnie dynamicznie wyciśnij sztangę do pozycji wyjściowej.', 'Powtórz ćwiczenie zgodnie z zaplanowaną liczbą powtórzeń.'],
  ARRAY['Klatka piersiowa'],
  ARRAY['Przedramiona', 'Triceps'],
  ARRAY['Utrzymuj napięcie mięśni brzucha przez cały czas, aby stabilizować tułów.', 'Kontroluj ruch opuszczania sztangi, aby uniknąć gwałtownego opadania.', 'Skup się na pracy mięśni klatki piersiowej i tricepsów podczas wyciskania.', 'Nie blokuj łokci w górnej pozycji, aby utrzymać napięcie mięśniowe.', 'Oddychaj regularnie – wdech przy opuszczaniu sztangi i wydech przy wyciskaniu.'],
  ARRAY['Nieutrzymywanie prostych nadgarstków, co prowadzi do potencjalnego nadwyrężenia nadgarstków.', 'Pozwalanie łokciom na nadmierne rozchodzenie się na boki, co zmniejsza stabilność barków.', 'Wyginanie dolnej części pleców, co może dezaktywować mięśnie rdzenia.', 'Odbijanie sztangi od podłogi, co prowadzi do utraty kontroli i zmniejszenia zaangażowania mięśni.', 'Nieprawidłowe ustawienie sztangi względem środka klatki piersiowej, co powoduje nierównomierne rozłożenie nacisku.', 'Używanie zbyt szerokiego uchwytu, co ogranicza zakres ruchu i mobilność barków.', 'Zbyt szybkie opuszczanie sztangi, co kompromituje kontrolę i zwiększa ryzyko kontuzji.', 'Zaniedbywanie retrakcji łopatek, co zmniejsza wsparcie górnej części pleców.', 'Naciskanie z nierówną siłą, co prowadzi do nierównomiernego rozwoju mięśni.', 'Niepełne zaangażowanie tricepsów, co ogranicza siłę wyciskania.']
),
(
  'Wyciskanie linek wyciągu górnego stojąc',
  'chest',
  'intermediate',
  'cable',
  'reps',
  'Wyciskanie linek na bramie wyciągu górnego to ćwiczenie izolujące mięśnie klatki piersiowej, szczególnie angażujące mięśnie piersiowe większe. Wykonywane jest na maszynie z linkami, co pozwala na stałe napięcie mięśni w całym zakresie ruchu.',
  ARRAY['Ustaw wysokość linek na poziomie ramion i wybierz odpowiedni ciężar.', 'Stań w środku maszyny, chwyć uchwyty obiema rękami i zrób krok do przodu, aby napiąć linki.', 'Ustaw stopy na szerokość bioder, lekko ugnij kolana i pochyl się nieco do przodu.', 'Zacznij ruch od pozycji, w której ramiona są rozłożone na boki, a łokcie lekko zgięte.', 'Ściśnij mięśnie klatki piersiowej i przyciągnij uchwyty do siebie przed klatką piersiową, utrzymując łokcie lekko zgięte.', 'Powoli wróć do pozycji wyjściowej, kontrolując ruch i utrzymując napięcie w mięśniach.', 'Powtórz ćwiczenie zgodnie z zaplanowaną liczbą powtórzeń.'],
  ARRAY['Klatka piersiowa'],
  ARRAY['Barki', 'Triceps'],
  ARRAY['Skup się na pracy mięśni klatki piersiowej, unikaj nadmiernego angażowania ramion.', 'Kontroluj tempo ruchu – unikaj gwałtownych szarpnięć.', 'Utrzymuj stałe napięcie w mięśniach przez cały czas trwania ćwiczenia.', 'Oddychaj regularnie – wydychaj powietrze podczas przyciągania uchwytów do siebie, a wdychaj podczas powrotu do pozycji wyjściowej.', 'Zwróć uwagę na prawidłową postawę – plecy powinny być proste, a brzuch napięty.'],
  ARRAY['Zbyt duże rozchylenie łokci, co zmniejsza zaangażowanie klatki piersiowej i zwiększa obciążenie barków.', 'Zbyt duże pochylenie do przodu lub do tyłu, co wpływa na równowagę i stabilność rdzenia.', 'Używanie zbyt dużego ciężaru, co prowadzi do złej formy i zmniejszonej kontroli.', 'Pozwalanie kablom na zbyt dalekie cofanie ramion, co grozi kontuzją barków.', 'Nieutrzymywanie mocnego ustawienia nadgarstków, co powoduje napięcie nadgarstków.', 'Brak zaangażowania rdzenia, co skutkuje mniej stabilną podstawą.', 'Pośpiech w ruchu, co zmniejsza czas pod napięciem i skuteczność.', 'Niedbanie o utrzymanie lekkiego zgięcia w łokciach na końcu wyciskania, co grozi napięciem stawów.', 'Używanie pędu zamiast kontrolowanego skurczu mięśni, co zmniejsza efektywność treningu.', 'Nieprawidłowe ustawienie wysokości kabli, co prowadzi do niewłaściwego celowania w mięśnie klatki piersiowej.']
),
(
  'Wyciskanie sztangi na ławce dodatniej',
  'chest',
  'intermediate',
  'barbell',
  'reps',
  'Wyciskanie sztangi na ławce dodatniej to ćwiczenie ukierunkowane na rozwój górnej części mięśni piersiowych, a także angażujące mięśnie naramienne i tricepsy. Wykonywane na ławce ustawionej pod kątem 30-45 stopni, pozwala na większe zaangażowanie górnych partii klatki piersiowej w porównaniu do tradycyjnego wyciskania na ławce poziomej.',
  ARRAY['Ustaw ławkę pod kątem 30-45 stopni.', 'Połóż się na ławce, stopy stabilnie na podłożu.', 'Chwyć sztangę nachwytem, dłonie nieco szerzej niż szerokość barków.', 'Zdejmij sztangę ze stojaka i utrzymuj ją nad klatką piersiową z wyprostowanymi ramionami.', 'Powoli opuszczaj sztangę w kierunku górnej części klatki piersiowej, kontrolując ruch.', 'Gdy sztanga znajdzie się tuż nad klatką piersiową, zatrzymaj ruch na chwilę.', 'Wyciskaj sztangę do góry, wracając do pozycji wyjściowej z wyprostowanymi ramionami.'],
  ARRAY['Klatka piersiowa'],
  ARRAY['Barki', 'Triceps'],
  ARRAY['Upewnij się, że kąt ławki nie jest zbyt stromy, aby uniknąć nadmiernego obciążenia barków.', 'Kontroluj ruch zarówno podczas opuszczania, jak i wyciskania sztangi.', 'Nie blokuj łokci w górnej pozycji – utrzymuj lekkie zgięcie dla ochrony stawów.', 'Skup się na pracy mięśni piersiowych, unikając nadmiernego angażowania ramion.', 'Oddychaj regularnie – wdech przy opuszczaniu sztangi, wydech przy jej wyciskaniu.'],
  ARRAY['Nadmierne wyginanie dolnej części pleców, zmniejszające zaangażowanie klatki piersiowej.', 'Opuszczanie sztangi zbyt wysoko na klatce piersiowej, zwiększające obciążenie barków.', 'Zbyt szerokie rozstawienie łokci, ryzykując uszkodzenie barków.', 'Odbijanie sztangi od klatki piersiowej, prowadzące do słabej kontroli mięśni.', 'Nieutrzymywanie stabilnej pozycji nadgarstków, ryzykując ich nadwyrężenie.', 'Nieużywanie pełnego zakresu ruchu, ograniczające aktywację mięśni.', 'Podnoszenie bioder z ławki, co obniża stabilność.', 'Pozwalanie sztandze na przesuwanie się do przodu, zmniejszając aktywację klatki piersiowej.', 'Używanie zbyt dużego ciężaru, poświęcając formę na rzecz obciążenia.', 'Zaniedbywanie zaangażowania mięśni brzucha, prowadzące do zmniejszonej stabilności.']
),
(
  'Pompki Superman’a',
  'chest',
  'beginner',
  'bodyweight',
  'reps',
  'Pompki Superman’a to zaawansowane ćwiczenie kalisteniczne, które angażuje wiele grup mięśniowych jednocześnie, w tym mięśnie klatki piersiowej, ramion, pleców oraz mięśnie rdzenia. Ćwiczenie to wymaga dużej siły i stabilizacji, ponieważ polega na jednoczesnym unoszeniu rąk i nóg w pozycji pompki.',
  ARRAY['Rozpocznij w pozycji pompki z rękami rozstawionymi nieco szerzej niż szerokość barków.', 'Napnij mięśnie brzucha i pośladków, aby utrzymać ciało w linii prostej od głowy do pięt.', 'Zginając łokcie, opuść ciało w dół, aż klatka piersiowa znajdzie się tuż nad podłogą.', 'W momencie najniższego punktu ruchu, dynamicznie wyprostuj ramiona i jednocześnie unieś ręce oraz nogi od podłogi.', 'Staraj się utrzymać równowagę i kontrolę podczas unoszenia kończyn.', 'Powoli wróć do pozycji wyjściowej i powtórz ruch.'],
  ARRAY['Klatka piersiowa'],
  ARRAY['Brzuch', 'Plecy', 'Barki', 'Triceps'],
  ARRAY['Upewnij się, że twoje ciało jest w pełni rozciągnięte podczas unoszenia rąk i nóg.', 'Skup się na równomiernym rozłożeniu ciężaru ciała podczas całego ruchu.', 'Oddychaj regularnie – wdech przy opuszczaniu ciała, wydech przy unoszeniu.', 'Jeśli jesteś początkujący, zacznij od mniejszej liczby powtórzeń i stopniowo zwiększaj intensywność.', 'Unikaj wyginania dolnej części pleców – utrzymuj napięcie mięśni brzucha przez cały czas.'],
  ARRAY['Nieangażowanie mięśni brzucha, co prowadzi do opadania dolnej części pleców.', 'Nieprawidłowe ustawienie rąk, powodujące brak równowagi i zmniejszenie siły.', 'Niewystarczające wyprostowanie ramion, ograniczające zakres ruchu.', 'Podnoszenie klatki piersiowej zbyt wysoko, co powoduje napięcie dolnej części pleców.', 'Słaba koordynacja między unoszeniem ramion a nóg, zakłócająca płynność ruchu.', 'Zaniedbywanie utrzymania prostej linii ciała, co powoduje nieprawidłową formę.', 'Zbyt ciężkie lądowanie, zwiększające ryzyko nadwyrężenia nadgarstków i ramion.', 'Zbyt szybkie wykonywanie ruchu, prowadzące do utraty kontroli i precyzji.']
),
(
  'Koreańskie pompki na poręczach',
  'chest',
  'intermediate',
  'bodyweight',
  'reps',
  'Koreańskie pompki na poręczach to zaawansowane ćwiczenie siłowe, które koncentruje się na wzmocnieniu mięśni klatki piersiowej, tricepsów oraz przednich części barków. Ćwiczenie to wymaga dużej siły i stabilności, ponieważ wykonywane jest na poręczach, co dodatkowo angażuje mięśnie stabilizujące.',
  ARRAY['Ustaw się pomiędzy poręczami, chwytając je mocno dłońmi skierowanymi do siebie.', 'Podnieś ciało do pozycji wyjściowej, prostując ramiona i unosząc nogi do tyłu, tak aby ciało było w linii prostej.', 'Zacznij opuszczać ciało, zginając łokcie i kierując je na zewnątrz. Kontroluj ruch, aby nie opadać zbyt szybko.', 'Opuszczaj się do momentu, gdy ramiona będą równoległe do podłoża lub nieco poniżej.', 'Zatrzymaj się na chwilę w dolnej pozycji, a następnie dynamicznie wyprostuj ramiona, wracając do pozycji wyjściowej.', 'Powtórz ruch określoną liczbę razy, utrzymując kontrolę nad ciałem przez cały czas.'],
  ARRAY['Klatka piersiowa'],
  ARRAY['Barki', 'Triceps'],
  ARRAY['Upewnij się, że poręcze są stabilne i odpowiednio rozstawione, aby uniknąć kontuzji.', 'Skup się na utrzymaniu napięcia mięśniowego w całym ciele podczas wykonywania ćwiczenia.', 'Oddychaj równomiernie – wdychaj powietrze podczas opuszczania ciała i wydychaj podczas unoszenia.', 'Jeśli jesteś początkujący, zacznij od mniejszej liczby powtórzeń i stopniowo zwiększaj intensywność treningu.', 'Unikaj zbyt szybkiego opuszczania ciała – kontroluj ruch, aby maksymalnie zaangażować mięśnie.'],
  ARRAY['Nieutrzymywanie prostej linii ciała, co prowadzi do nadmiernego wyginania lub opadania.', 'Pozwalanie na wysuwanie się ramion do przodu, co zmniejsza zaangażowanie łopatek.', 'Zbyt szybkie opadanie w dipie bez kontrolowanego zejścia.', 'Nieosiąganie pełnego zakresu ruchu przez zatrzymywanie się zbyt wysoko lub zbyt nisko.', 'Zaniedbywanie trzymania łokci blisko ciała, co powoduje ich rozchodzenie się.', 'Używanie pędu zamiast siły mięśni do wypchnięcia się w górę.', 'Niewystarczające zaangażowanie mięśni brzucha, co prowadzi do niestabilności.', 'Nadmierne wyciąganie szyi przez patrzenie w górę lub w dół zamiast utrzymywania jej w neutralnej pozycji.']
),
(
  'Wyciskanie na ławce dodatniej z wyciągu dolnego',
  'chest',
  'intermediate',
  'cable',
  'reps',
  'Wyciskanie na ławce dodatniej z wyciągu dolnego to ćwiczenie angażujące głównie górną część klatki piersiowej, a także mięśnie naramienne i tricepsy. Ćwiczenie to jest wykonywane na ławce ustawionej pod kątem około 30-45 stopni, z użyciem wyciągu dolnego, co pozwala na ciągłe napięcie mięśni w całym zakresie ruchu.',
  ARRAY['Ustaw ławkę pod kątem 30-45 stopni i usiądź na niej, upewniając się, że stopy są stabilnie oparte na podłożu.', 'Chwyć uchwyty wyciągu dolnego dłońmi skierowanymi do przodu.', 'Rozpocznij ruch od pozycji, w której uchwyty są na wysokości klatki piersiowej, a ramiona są zgięte.', 'Wyciskaj uchwyty do góry, prostując ramiona, aż będą one niemal całkowicie wyprostowane, ale nie blokuj łokci.', 'Powoli opuść uchwyty do pozycji wyjściowej, kontrolując ruch i utrzymując napięcie mięśniowe.'],
  ARRAY['Klatka piersiowa'],
  ARRAY['Przedramiona', 'Triceps'],
  ARRAY['Utrzymuj łopatki ściągnięte i stabilne przez cały czas trwania ćwiczenia, aby zminimalizować ryzyko kontuzji.', 'Kontroluj tempo ruchu – wykonuj fazę unoszenia dynamicznie, a opuszczania powoli i kontrolowanie.', 'Unikaj przeprostowywania łokci w górnej fazie ruchu, aby nie obciążać stawów.', 'Skup się na pracy mięśni klatki piersiowej – staraj się nie angażować nadmiernie ramion.', 'Oddychaj regularnie – wydychaj powietrze podczas unoszenia ciężaru i wdychaj podczas opuszczania.'],
  ARRAY['Pozwalanie na nadmierne rozchylenie łokci, co zmniejsza zaangażowanie klatki piersiowej i zwiększa obciążenie barków.', 'Nadmierne wyginanie dolnej części pleców, co kompromituje wyrównanie kręgosłupa i stabilność.', 'Używanie zbyt dużego ciężaru, co prowadzi do niekontrolowanego ruchu i zmniejszonej aktywacji mięśni.', 'Nieutrzymywanie stabilnej pozycji barków, co powoduje nadmierny ruch barków i potencjalne obciążenie stawów.', 'Zbyt szybkie opuszczanie kabli, co zmniejsza czas pod napięciem i kontrolę.', 'Niepełne prostowanie ramion na szczycie ruchu, co ogranicza zakres ruchu i aktywację mięśni.', 'Ustawianie ławki pod zbyt stromym kątem, co przesuwa skupienie z górnej części klatki piersiowej.', 'Pozwalanie na zginanie nadgarstków do tyłu, co zwiększa obciążenie nadgarstków i przedramion.', 'Zaniedbywanie zaangażowania mięśni brzucha, co prowadzi do niestabilności i zmniejszonego transferu mocy.', 'Pozwalanie na przesunięcie kabli poza wyrównanie z klatką piersiową, co powoduje nierównomierne zaangażowanie mięśni.']
),
(
  'Wyciskanie linek na wyciągu stojąc',
  'chest',
  'intermediate',
  'cable',
  'reps',
  'Wyciskanie linek na wyciągu stojąc to ćwiczenie izolujące mięśnie klatki piersiowej, szczególnie angażujące dolną część piersiową. Wykonywane jest przy użyciu wyciągu górnego z linkami, co pozwala na kontrolowane napięcie mięśni przez cały zakres ruchu.',
  ARRAY['Ustaw wyciąg górny na odpowiedniej wysokości, tak aby linki były na poziomie ramion.', 'Stań w lekkim rozkroku, stopy na szerokość bioder, plecy proste.', 'Chwyć uchwyty linek obiema rękami, dłonie skierowane do siebie.', 'Zrób krok do przodu, aby napiąć linki i ustabilizować pozycję.', 'Zegnij lekko kolana i pochyl się delikatnie do przodu w biodrach.', 'Rozpocznij ruch, przyciągając uchwyty do siebie, zbliżając dłonie przed klatką piersiową.', 'Utrzymaj napięcie w mięśniach klatki piersiowej przez chwilę w końcowej fazie ruchu.', 'Powoli wróć do pozycji wyjściowej, kontrolując ruch.'],
  ARRAY['Klatka piersiowa'],
  ARRAY['Barki', 'Triceps'],
  ARRAY['Utrzymuj stałe napięcie mięśniowe przez cały czas trwania ćwiczenia.', 'Nie blokuj łokci w końcowej fazie ruchu, aby utrzymać napięcie w mięśniach.', 'Oddychaj regularnie – wydychaj powietrze podczas przyciągania linek i wdychaj podczas powrotu do pozycji wyjściowej.', 'Skup się na pracy mięśni klatki piersiowej, unikaj angażowania ramion i pleców.', 'Kontroluj tempo – unikaj zbyt szybkich ruchów, które mogą prowadzić do utraty kontroli nad ciężarem.'],
  ARRAY['Zbyt szerokie rozstawienie łokci, co zmniejsza zaangażowanie klatki piersiowej i zwiększa napięcie w barkach.', 'Nadmierne wyginanie dolnej części pleców, co prowadzi do słabego zaangażowania mięśni brzucha i potencjalnego dyskomfortu w dolnej części pleców.', 'Pozwalanie na unoszenie się barków, co zmniejsza aktywację klatki piersiowej i zwiększa napięcie w szyi.', 'Używanie pędu poprzez pochylanie się do przodu lub do tyłu, co osłabia kontrolę i zaangażowanie mięśni.', 'Nieprawidłowe ustawienie kabli względem linii klatki piersiowej, co prowadzi do niewłaściwego kierunku siły i zmniejszonej skuteczności.', 'Nadmierne prostowanie ramion na końcu wyciskania, co powoduje niepotrzebne obciążenie stawów.', 'Zaniedbywanie utrzymania stabilnej postawy, co wpływa na równowagę i wydajność siłową.', 'Pośpiech podczas wykonywania powtórzeń, co prowadzi do złej formy i zmniejszonej aktywacji mięśni.', 'Nieściąganie łopatek na początku, co zmniejsza zaangażowanie klatki piersiowej.', 'Używanie zbyt szerokiego lub zbyt wąskiego uchwytu, co wpływa na zakres ruchu i celowanie w mięśnie.']
),
(
  'Pompki na pięściach',
  'chest',
  'intermediate',
  'bodyweight',
  'reps',
  'Pompki na pięściach to wariant klasycznych pompek, który angażuje głównie mięśnie klatki piersiowej, tricepsy oraz mięśnie barków. Wykonywane na pięściach, zwiększają stabilność nadgarstków i mogą pomóc w ich wzmocnieniu. Ćwiczenie to wymaga większej siły i stabilności niż tradycyjne pompki, co czyni je bardziej zaawansowanym wyborem dla osób trenujących.',
  ARRAY['Rozpocznij w pozycji deski, ustawiając ciało w linii prostej od głowy do pięt.', 'Umieść pięści na podłodze na szerokość barków, z kciukami skierowanymi do środka.', 'Utrzymuj napięcie w mięśniach brzucha i pośladkach, aby zachować stabilność.', 'Zginaj łokcie, obniżając ciało w kontrolowany sposób, aż klatka piersiowa znajdzie się tuż nad podłogą.', 'Wypchnij ciało do góry, prostując łokcie i wracając do pozycji wyjściowej.'],
  ARRAY['Klatka piersiowa'],
  ARRAY['Brzuch', 'Barki', 'Triceps'],
  ARRAY['Upewnij się, że nadgarstki są ustawione bezpośrednio pod barkami, aby zminimalizować ryzyko kontuzji.', 'Kontroluj ruchy, nie pozwalając ciału opadać gwałtownie na dół.', 'Oddychaj regularnie – wdech podczas opuszczania ciała i wydech przy wypychaniu do góry.', 'Jeśli czujesz dyskomfort w nadgarstkach, spróbuj zmienić pozycję pięści lub rozważ użycie maty dla dodatkowej amortyzacji.', 'Zacznij od mniejszej liczby powtórzeń i stopniowo zwiększaj intensywność wraz z poprawą siły.'],
  ARRAY['Pozwalanie nadgarstkom na zapadanie się do wewnątrz lub na zewnątrz, co osłabia stabilność i zwiększa obciążenie stawów.', 'Nieutrzymywanie prostej linii od głowy do pięt, co prowadzi do opadania bioder lub uniesienia pośladków, zmniejszając zaangażowanie mięśni brzucha.', 'Ustawianie rąk zbyt szeroko lub zbyt wąsko, co wpływa na aktywację mięśni ramion i klatki piersiowej.', 'Niepełne prostowanie łokci na szczycie ruchu, co ogranicza zakres ruchu i zaangażowanie mięśni.', 'Opuszczanie głowy, co obciąża szyję i zaburza wyrównanie kręgosłupa.', 'Pośpiech podczas powtórzeń, poświęcając formę i kontrolę na rzecz szybkości.', 'Zaniedbywanie angażowania mięśni brzucha, co skutkuje brakiem stabilności i zwiększonym ryzykiem obciążenia dolnej części pleców.', 'Zginanie palców zamiast utrzymywania ich prostych, co zmniejsza skuteczność ćwiczenia.']
