-- Block 2: workout_templates
INSERT INTO workout_templates (name, description, target_goal, difficulty) VALUES
('Siłowy — Pełne Ciało (Początkujący)', 'Klasyczny plan siłowy na całe ciało dla początkujących. Trzy sesje tygodniowo z priorytetem na ćwiczenia wielostawowe przy niskim obciążeniu. Buduje fundament siły i właściwych wzorców ruchowych.', 'strength', 'beginner'),
('Hipertrofia — Push Pull Nogi', 'Klasyczny split Push-Pull-Nogi dla średniozaawansowanych. Umożliwia wysoką częstotliwość treningu każdej grupy mięśniowej przy optymalnej objętości dla hipertrofii.', 'hypertrophy', 'intermediate'),
('Ogólna Sprawność — Obwodowy (Początkujący)', 'Trening obwodowy dla początkujących poprawiający ogólną kondycję i sprawność fizyczną. Ćwiczenia wykonywane jedno po drugim z krótkimi przerwami — angażuje całe ciało.', 'general_fitness', 'beginner'),
('Redukcja — Pełne Ciało (Średniozaawansowany)', 'Plan treningowy pełnego ciała zorientowany na spalanie tkanki tłuszczowej. Wysokie powtórzenia, krótkie przerwy i połączenie ćwiczeń wielostawowych z elementami cardio.', 'fat_loss', 'intermediate'),
('Siłowy — Góra/Dół (Średniozaawansowany)', 'Split Góra/Dół dla średniozaawansowanych — 4 dni tygodniowo. Dwie sesje górnych partii i dwie dolnych, z priorytetem ćwiczeń siłowych wielostawowych.', 'strength', 'intermediate'),
('Hipertrofia — Pełne Ciało (Zaawansowany)', 'Zaawansowany plan pełnego ciała skupiony na maksymalnym wzroście mięśniowym. Łączy ćwiczenia złożone z izolowanymi, z dużą objętością i kontrolowanym tempem.', 'hypertrophy', 'advanced'),
('Wytrzymałość Cardio — Obwodowy', 'Trening obwodowy dla wytrzymałości sercowo-naczyniowej. Minimalny sprzęt, krótkie przerwy, wysoka intensywność.', 'cardio_endurance', 'intermediate'),
('Siłowy — Push Pull Nogi (Zaawansowany)', 'Zaawansowany 6-dniowy split Push-Pull-Nogi z naciskiem na siłę maksymalną. Niskie powtórzenia, progresja obciążeń i złożone wzorce ruchowe.', 'strength', 'advanced');

